<script setup>
import { ref, computed, onMounted } from 'vue'
import { Boxes, LayoutDashboard, Sparkles, Package, History, ShieldCheck, ArrowUpRight, ArrowRight, RefreshCw, Search, LogOut, Check, X, Activity, ChevronRight, CircleHelp, SlidersHorizontal, LoaderCircle, Command, Database, Clock3, AlertTriangle } from 'lucide-vue-next'

const user = ref(null), initializing = ref(true), active = ref('dashboard'), error = ref(''), loading = ref(false), refreshing = ref(false)
const credentials = ref({username:'admin', password:''}), csrf = ref(null)
const overview = ref({}), runs = ref([]), products = ref([]), audit = ref([]), result = ref(null), selectedRun = ref(null), search = ref('')
const form = ref({user_id:'user_001',scene:'homepage',num_items:5,categories:'手机,耳机',avg_order_amount:500})
const nav = [{id:'dashboard',name:'运营概览',icon:LayoutDashboard},{id:'recommend',name:'推荐工作台',icon:Sparkles},{id:'products',name:'商品目录',icon:Package},{id:'history',name:'调用记录',icon:History},{id:'audit',name:'安全审计',icon:ShieldCheck}]
const titles={dashboard:'运营概览',recommend:'推荐工作台',products:'商品目录',history:'调用记录',audit:'安全审计'}
const healthy = computed(()=>overview.value.agent_service?.status==='healthy')
const successRate = computed(()=>overview.value.total ? Math.round(overview.value.successful / overview.value.total * 100)+'%' : '—')
const filteredProducts = computed(()=>products.value.filter(p=>(p.name+p.category+p.product_id).toLowerCase().includes(search.value.toLowerCase())))
const filteredRuns = computed(()=>runs.value.filter(r=>(r.user_id+r.id+r.status).toLowerCase().includes(search.value.toLowerCase())))
const labels={SUCCESS:'执行成功',DEGRADED:'部分降级',FAILED:'执行失败'}
const agentLabels={user_profile:'用户画像',product_rec:'商品推荐',marketing_copy:'营销文案',inventory:'库存决策'}
const money = n => new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY',maximumFractionDigits:0}).format(n)
const when = t => new Date(t).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const iconFor = p => ({手机:'◫',耳机:'◉',平板:'▱',笔记本:'▰',配件:'⌁',存储:'▥',穿戴:'◷',无人机:'✣',游戏机:'⌘',显示器:'▣'}[p.category] || '◇')
async function token() { csrf.value = await (await fetch('/api/csrf',{credentials:'same-origin'})).json() }
async function api(path, options={}) {
  const headers={...options.headers}
  if (options.method && options.method!=='GET') { if(!csrf.value) await token(); headers[csrf.value.headerName]=csrf.value.token }
  const res=await fetch('/api'+path,{credentials:'same-origin',...options,headers})
  if(res.status===204) return null
  const data=await res.json().catch(()=>({message:'服务器返回了无效响应'}))
  if(!res.ok) { if(res.status===401 && path!=='/login') user.value=null; throw new Error(data.message || `请求失败 (${res.status})`) }
  return data
}
async function refresh() {
  refreshing.value=true
  try { const data=await Promise.all([api('/overview'),api('/runs'),api('/products'),api('/audit')]); [overview.value,runs.value,products.value,audit.value]=data }
  catch(e){error.value=e.message} finally{refreshing.value=false}
}
async function login() {
  loading.value=true; error.value=''
  try { await token(); await api('/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(credentials.value)}); credentials.value.password=''; csrf.value=null; await token(); user.value=await api('/me'); await refresh() }
  catch(e){error.value=e.message} finally{loading.value=false}
}
async function logout(){ try{await api('/logout',{method:'POST'});user.value=null;csrf.value=null;result.value=null;selectedRun.value=null}catch(e){error.value=e.message} }
function navigate(id){active.value=id;search.value='';error.value=''}
async function recommend(){
  if(!form.value.user_id.trim()){error.value='请输入用户编号';return}
  loading.value=true; error.value=''; result.value=null
  try{
    result.value=await api('/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({user_id:form.value.user_id.trim(),scene:form.value.scene,num_items:Number(form.value.num_items),context:{recent_views:form.value.categories.split(/[,，]/).map(x=>x.trim()).filter(Boolean),avg_order_amount:Number(form.value.avg_order_amount)}})})
    await refresh()
  }catch(e){error.value=e.message;await refresh()}finally{loading.value=false}
}
async function openRun(id){try{const data=await api('/runs/'+id);selectedRun.value={...data,id}}catch(e){error.value=e.message}}
function copyFor(product,response){return response?.marketing_copies?.find(c=>c.product_id===product.product_id)?.copy || '本次未生成该商品的营销文案'}
onMounted(async()=>{try{await token();user.value=await api('/me');await refresh()}catch{}finally{initializing.value=false}})
</script>

<template>
  <div v-if="initializing" class="boot"><LoaderCircle class="spin"/> 正在连接运营控制台…</div>
  <div v-else-if="!user" class="login-screen">
    <section class="login-story"><a class="brand"><span class="brand-icon"><Boxes :size="24"/></span> Commerce<span class="brand-os">OS</span></a><div class="login-copy"><div class="eyebrow">MULTI-AGENT COMMERCE PLATFORM</div><h1>让每一次推荐，<br>都更懂你的用户。</h1><p>连接用户洞察、商品策略与营销创意。<br>在一个工作台里，完成多 Agent 协同运营。</p><div class="login-pipeline"><span>用户画像</span><ArrowRight :size="16"/><span>智能推荐</span><ArrowRight :size="16"/><span>营销决策</span></div></div><small>Commerce OS / 企业运营控制台 · 本地开发版</small></section>
    <section class="login-form"><div class="eyebrow">WELCOME BACK</div><h2>登录工作空间</h2><p>使用管理员账号继续</p><form @submit.prevent="login"><label>用户名<input v-model="credentials.username" autocomplete="username" required maxlength="80"/></label><label>密码<input v-model="credentials.password" type="password" autocomplete="current-password" required/></label><div v-if="error" class="error" role="alert">{{error}}</div><button class="primary wide" :disabled="loading"><LoaderCircle v-if="loading" class="spin" :size="17"/>{{loading?'正在登录':'进入控制台'}}<ArrowRight :size="17"/></button></form><div class="login-hint"><ShieldCheck :size="18"/><span>首次登录凭据位于服务端<br><code>backend/data/initial-admin.txt</code></span></div></section>
  </div>
  <div v-else class="shell">
    <aside class="sidebar"><a class="brand" @click="navigate('dashboard')"><span class="brand-icon"><Boxes :size="23"/></span>Commerce<span class="brand-os">OS</span></a><div class="workspace"><span class="workspace-avatar">C</span><div><strong>默认工作空间</strong><small>Enterprise workspace</small></div><span class="workspace-dot"></span></div><div class="nav-caption">工作空间</div><nav><button v-for="item in nav" :key="item.id" :aria-label="item.name" :title="item.name" :class="{selected:active===item.id}" @click="navigate(item.id)"><component :is="item.icon" :size="19"/><span>{{item.name}}</span><span v-if="item.id==='history' && runs.length" class="nav-count">{{runs.length}}</span></button></nav><div class="sidebar-bottom"><div class="service-card"><span class="live-dot" :class="{offline:!healthy}"></span><strong>{{healthy?'Agent 服务已连接':'Agent 服务未连接'}}</strong><p>{{overview.agent_service?.model || '请检查 Python 服务'}}</p></div><button class="user-menu" @click="logout"><span class="avatar">A</span><span><strong>{{user.username}}</strong><small>系统管理员</small></span><LogOut :size="17"/></button></div></aside>
    <div class="main-area"><header class="topbar"><div class="breadcrumb">工作空间<ChevronRight :size="14"/><span>{{titles[active]}}</span></div><div class="top-actions"><span class="environment"><span></span>本地开发环境</span><button class="icon-btn" title="刷新数据" aria-label="刷新数据" @click="refresh" :disabled="refreshing"><RefreshCw :size="17" :class="{spin:refreshing}"/></button><button class="icon-btn mobile-logout" title="退出登录" aria-label="退出登录" @click="logout"><LogOut :size="17"/></button></div></header>
    <main><div class="page-heading"><div><div class="eyebrow">{{active==='dashboard'?'WORKSPACE OVERVIEW':active==='recommend'?'RECOMMENDATION STUDIO':'COMMERCE OPERATIONS'}}</div><h1>{{titles[active]}}<span class="heading-dot">.</span></h1><p>{{({dashboard:'从用户洞察到营销转化，让智能协作看得见。',recommend:'输入用户偏好，让四个 Agent 协同完成一次推荐。',products:'查看真实调用结果中出现过的商品快照。',history:'追踪每一次请求、执行状态与推荐结果。',audit:'记录管理员登录与推荐操作，保留可追溯的足迹。'})[active]}}</p></div><button v-if="active!=='recommend'" class="primary" @click="navigate('recommend')"><Sparkles :size="17"/>创建推荐<ArrowUpRight :size="16"/></button><span v-else class="pill muted"><ShieldCheck :size="14"/>服务端安全调用</span></div>
    <div v-if="error" class="error banner" role="alert"><AlertTriangle :size="18"/>{{error}}<button class="icon-btn" @click="error=''" aria-label="关闭错误"><X :size="16"/></button></div>

    <template v-if="active==='dashboard'">
      <section class="hero"><div><div class="hero-label"><span></span> YOUR AI OPERATIONS TEAM</div><h2>一个目标，<br>四位智能伙伴。</h2><p>洞察偏好、精选商品、校验库存、生成文案。<br>把繁琐的运营流程，交给协同工作的 Agent。</p><button class="hero-button" @click="navigate('recommend')">开始一次智能推荐<ArrowRight :size="17"/></button></div><div class="orchestration" aria-label="四个Agent协同示意"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hub"><Boxes :size="30"/><strong>Supervisor</strong><small>协同编排</small></div><div class="agent-node node-one"><span>01</span><strong>用户画像</strong><small>理解用户偏好</small></div><div class="agent-node node-two"><span>02</span><strong>商品推荐</strong><small>召回与智能排序</small></div><div class="agent-node node-three"><span>03</span><strong>库存决策</strong><small>实时可售校验</small></div><div class="agent-node node-four"><span>04</span><strong>营销文案</strong><small>个性化表达</small></div></div></section>
      <section class="stats"><article><div>累计推荐请求<Command :size="17"/></div><strong>{{overview.total || 0}}<small>次</small></strong><p>全部已记录的推荐任务</p></article><article><div>完整执行成功率<ShieldCheck :size="17"/></div><strong>{{successRate}}</strong><p>四个 Agent 均成功的请求占比</p></article><article><div>平均响应时间<Clock3 :size="17"/></div><strong>{{overview.total ? (overview.avg_duration_ms/1000).toFixed(1) : '—'}}<small>秒</small></strong><p>含模型推理与服务编排耗时</p></article><article><div>已发现商品<Package :size="17"/></div><strong>{{overview.product_count || 0}}<small>件</small></strong><p>来自历史推荐的商品快照</p></article></section>
      <div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h3>最近推荐任务</h3><p>每一次智能决策，都有迹可循</p></div><button class="text-btn" @click="navigate('history')">全部记录<ArrowUpRight :size="15"/></button></div><div v-if="!runs.length" class="empty"><div class="empty-icon"><History :size="25"/></div><h4>你的第一条推荐，值得期待</h4><p>创建推荐后，任务执行情况将显示在这里。</p><button class="secondary" @click="navigate('recommend')">创建第一条推荐<ArrowRight :size="15"/></button></div><div v-else class="table-wrap"><table><thead><tr><th>目标用户</th><th>执行状态</th><th>耗时</th><th>时间</th></tr></thead><tbody><tr v-for="run in runs.slice(0,5)" :key="run.id" @click="openRun(run.id)" class="clickable"><td><strong>{{run.user_id}}</strong><small>{{run.id.slice(0,8)}}</small></td><td><span class="status" :class="run.status.toLowerCase()">{{labels[run.status]}}</span></td><td>{{(run.duration_ms/1000).toFixed(1)}}s</td><td>{{when(run.created_at)}}</td></tr></tbody></table></div></section><section class="panel system-panel"><div class="panel-heading"><div><h3>服务运行状态</h3><p>连接状态与架构概览</p></div><Activity :size="18"/></div><div class="system-row"><span class="system-icon"><Boxes :size="20"/></span><div><strong>Java 业务服务</strong><small>Spring Boot · 安全与持久化</small></div><span class="live-dot"></span></div><div class="system-row"><span class="system-icon"><Sparkles :size="20"/></span><div><strong>多 Agent 推理服务</strong><small>{{overview.agent_service?.model || '未连接'}}</small></div><span class="live-dot" :class="{offline:!healthy}"></span></div><div class="system-row"><span class="system-icon"><Database :size="20"/></span><div><strong>运营数据存储</strong><small>H2 文件数据库 · 本地持久化</small></div><span class="live-dot"></span></div><div class="note"><CircleHelp :size="17"/><p>当前为开发版。商品使用原项目示例数据，指标来自真实调用记录。</p></div></section></div>
    </template>

    <template v-if="active==='recommend'"><div class="studio-grid"><section class="panel form-panel"><div class="panel-heading"><div><h3>推荐任务配置</h3><p>为目标用户创建个性化推荐</p></div><SlidersHorizontal :size="19"/></div><form @submit.prevent="recommend"><label>用户编号<span class="required">*</span><input v-model="form.user_id" required maxlength="100" placeholder="例如 user_001"/></label><label>推荐场景<select v-model="form.scene"><option value="homepage">首页推荐</option><option value="detail">商品详情</option><option value="cart">购物车推荐</option><option value="campaign">营销活动</option></select></label><label>兴趣类目<input v-model="form.categories" placeholder="手机,耳机,平板" maxlength="200"/><small>多个类目用逗号分隔</small></label><div class="form-row"><label>平均订单金额<input v-model="form.avg_order_amount" type="number" min="0" max="1000000" required/></label><label>推荐数量<input v-model="form.num_items" type="number" min="1" max="15" required/></label></div><div class="note"><Sparkles :size="17"/><p>提交后将调用百炼模型，按你的模型账户用量计费。</p></div><button class="primary wide" :disabled="loading || !healthy"><LoaderCircle v-if="loading" class="spin" :size="17"/><Sparkles v-else :size="17"/>{{loading?'Agent 正在协同执行…':'生成个性化推荐'}}<ArrowRight v-if="!loading" :size="16"/></button><p v-if="!healthy" class="form-warning">请先启动 Python Agent 服务，再刷新页面。</p></form></section><section class="result-area"><div v-if="loading" class="panel processing"><LoaderCircle class="spin" :size="34"/><h3>智能团队正在工作</h3><p>分析用户偏好，筛选商品，并生成专属文案。<br>模型推理可能需要几十秒，请保持页面打开。</p></div><div v-else-if="!result" class="panel empty result-empty"><div class="empty-icon"><Sparkles :size="30"/></div><div class="eyebrow">READY WHEN YOU ARE</div><h3>下一次好推荐，从这里开始</h3><p>填写左侧信息，查看推荐商品、营销文案<br>以及四个 Agent 的执行情况。</p><div class="empty-steps"><span>洞察</span><ArrowRight :size="14"/><span>推荐</span><ArrowRight :size="14"/><span>表达</span></div></div><template v-else><div class="result-summary"><div><span class="status" :class="result.status.toLowerCase()">{{labels[result.status]}}</span><h3>为 {{result.response.user_id}} 精选 {{result.response.products.length}} 件商品</h3><p>{{(result.response.total_latency_ms/1000).toFixed(1)}} 秒 · 实验分组 {{result.response.experiment_group}}</p></div></div><div v-if="result.status==='DEGRADED'" class="warning">部分 Agent 执行失败，本次结果包含降级输出。请展开执行详情查看原因。</div><div class="agent-results"><details v-for="(agent,key) in result.response.agent_results" :key="key"><summary><span class="agent-state" :class="{bad:!agent.success}"><Check v-if="agent.success" :size="13"/><X v-else :size="13"/></span>{{agentLabels[key] || key}}<small>{{(agent.latency_ms/1000).toFixed(1)}}s</small></summary><p>{{agent.success?'执行成功':agent.error || '执行失败'}}</p></details></div><div class="note copy-note"><CircleHelp :size="17"/><p>AI 营销文案为草稿，可能包含未经核实的优惠或商品描述，请人工审核后使用。</p></div><div class="product-grid"><article class="product-card" v-for="p in result.response.products" :key="p.product_id"><div class="product-art" :data-category="p.category"><span>{{iconFor(p)}}</span><small>{{p.category}}</small></div><div class="product-info"><span class="product-id">{{p.product_id}} · {{p.brand}}</span><h3>{{p.name}}</h3><div class="product-price">{{money(p.price)}}<small>库存 {{p.stock}}</small></div><div class="tags"><span v-for="tag in p.tags" :key="tag">{{tag}}</span></div><div class="marketing"><Sparkles :size="14"/><p>{{copyFor(p,result.response)}}</p></div></div></article></div></template></section></div></template>

    <template v-if="active==='products'"><section class="panel"><div class="panel-heading"><div><h3>推荐商品快照 <span class="count">{{products.length}}</span></h3><p>只读展示；价格与库存以最近一次推荐响应为准</p></div><div class="search"><Search :size="16"/><input v-model="search" placeholder="搜索商品、类目或编号"/></div></div><div class="empty" v-if="!products.length"><Package :size="30"/><h4>还没有商品快照</h4><p>完成一次推荐后，返回的商品会自动收录到这里。</p><button class="secondary" @click="navigate('recommend')">创建推荐</button></div><div v-else-if="!filteredProducts.length" class="empty"><Search :size="28"/><h4>没有匹配的商品</h4><p>试试其他关键词。</p></div><div v-else class="table-wrap"><table><thead><tr><th>商品</th><th>类目</th><th>品牌</th><th>价格</th><th>库存快照</th><th>标签</th></tr></thead><tbody><tr v-for="p in filteredProducts" :key="p.product_id"><td><strong>{{p.name}}</strong><small>{{p.product_id}}</small></td><td>{{p.category}}</td><td>{{p.brand}}</td><td>{{money(p.price)}}</td><td><span class="status" :class="p.stock<=0?'failed':p.stock<100?'degraded':'success'">{{p.stock}} 件</span></td><td><div class="tags"><span v-for="tag in p.tags" :key="tag">{{tag}}</span></div></td></tr></tbody></table></div></section></template>

    <template v-if="active==='history'"><section class="panel"><div class="panel-heading"><div><h3>推荐调用记录</h3><p>最近 100 条 · 点击记录查看请求和完整响应</p></div><div class="search"><Search :size="16"/><input v-model="search" placeholder="搜索用户、状态或任务 ID"/></div></div><div v-if="!filteredRuns.length" class="empty"><History :size="30"/><h4>{{runs.length?'没有匹配的调用':'暂无调用记录'}}</h4><p>创建推荐后即可在这里追踪执行过程。</p></div><div v-else class="table-wrap"><table><thead><tr><th>任务 ID</th><th>用户 / 操作人</th><th>场景</th><th>状态</th><th>耗时</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="run in filteredRuns" :key="run.id" class="clickable" @click="openRun(run.id)"><td class="mono">{{run.id.slice(0,8)}}</td><td><strong>{{run.user_id}}</strong><small>{{run.username}}</small></td><td>{{run.scene}}</td><td><span class="status" :class="run.status.toLowerCase()">{{labels[run.status]}}</span></td><td>{{(run.duration_ms/1000).toFixed(1)}}s</td><td>{{when(run.created_at)}}</td><td><ChevronRight :size="16"/></td></tr></tbody></table></div></section></template>

    <template v-if="active==='audit'"><section class="panel"><div class="panel-heading"><div><h3>操作审计日志</h3><p>最近 100 条安全与业务事件</p></div><span class="pill muted"><ShieldCheck :size="14"/>服务端记录</span></div><div v-if="!audit.length" class="empty">暂无审计事件</div><div v-else class="table-wrap"><table><thead><tr><th>操作人</th><th>事件类型</th><th>事件详情</th><th>时间</th></tr></thead><tbody><tr v-for="(event,i) in audit" :key="i"><td><strong>{{event.username}}</strong></td><td><span class="event-name">{{event.action}}</span></td><td class="mono">{{event.detail}}</td><td>{{when(event.created_at)}}</td></tr></tbody></table></div></section></template>
    <footer><span>Commerce OS <span class="footer-sep">/</span> 多 Agent 智能运营</span><span>Spring Boot + Vue · Development</span></footer>
    </main></div>
    <div v-if="selectedRun" class="modal-backdrop" @click.self="selectedRun=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="run-title"><div class="panel-heading"><div><h3 id="run-title">推荐任务详情</h3><p class="mono">{{selectedRun.id}}</p></div><button class="icon-btn" @click="selectedRun=null" aria-label="关闭详情"><X :size="20"/></button></div><div class="modal-body"><span class="status" :class="selectedRun.status.toLowerCase()">{{labels[selectedRun.status]}}</span><p v-if="selectedRun.error" class="error">{{selectedRun.error}}</p><h4>请求参数</h4><pre>{{JSON.stringify(selectedRun.request,null,2)}}</pre><h4>完整响应</h4><pre>{{JSON.stringify(selectedRun.response,null,2)}}</pre></div></section></div>
  </div>
</template>
